import test from"node:test";import assert from"node:assert/strict";import{createHash}from"node:crypto";import{buildGovernanceEvidenceBundleEntry as entry}from"../src/governance-evidence-bundle-entry.js";import{buildGovernanceEvidenceBundleManifest as manifest}from"../src/governance-evidence-bundle-manifest.js";import{buildGovernanceEvidenceBundleCompleteness as complete}from"../src/governance-evidence-bundle-completeness.js";import{buildGovernanceEvidenceBundleReplay as replay}from"../src/governance-evidence-bundle-replay.js";const h=x=>createHash("sha256").update(x).digest("hex"),run=()=>{let entries=["provenance","freshness","audit"].map((e,i)=>entry({evidenceClass:e,artifactHash:h("a"+i),provenanceHash:h("p"+i),freshnessHash:h("f"+i)})),m=manifest({entries:entries.reverse(),snapshotHash:h("s"),policyHash:h("policy")}),c=complete({manifest:m,requiredClasses:["audit","freshness","provenance"]}),r=replay({manifestHash:m.manifestHash,completenessHash:h(JSON.stringify(c)),environmentHash:h("env"),resultHash:h("result")});return{m,c,r}};test("405 canonical bundle is complete immutable replayable",()=>{let a=run(),b=run();assert.deepEqual(a,b);assert.equal(a.c.complete,true);assert.equal(a.c.missing.length,0);assert.ok(Object.isFrozen(a.m.entries));assert.match(a.r.replayHash,/^[a-f0-9]{64}$/)});test("405 transport replay preserves canonical values",()=>{let a=run(),wire=JSON.stringify(a.m,null,2);assert.deepEqual(JSON.parse(wire),a.m);assert.equal(wire.includes("payload"),false)});